@Injectable()
export class ValidateIngress implements NestInterceptor {
  intercept(ctx: ExecutionContext, next: CallHandler) {
    const err = IngressRules.check(ctx.switchToHttp().getRequest());
    if (err) throw new BadRequestException(err);   // next.handle() never runs
    return next.handle();
  }
}
